window.TASK_BANKS[54] = {"version":1,"topicId":54,"tasks":[{"id":"54.1","codeLang":"python","answer":"[2, 5, 2, 5]\n[4, 10]","answerLang":"text","explanation":"Умножение списка повторяет его элементы. NumPy применяет умножение к каждому числу. tolist() переводит результат в обычный список для понятного вывода.","verified":"3.14","wrong":["[4, 10]\n[4, 10]","[2, 5, 2, 5]\n[2, 5, 2, 5]"]},{"id":"54.2","codeLang":"python","answer":"import numpy as np\ndef scale_readings(values, factor):\n    return np.array(values, dtype=np.float64) * factor","answerLang":"python","explanation":"Список преобразуется в числовой массив с явно выбранным типом. Арифметика работает с элементами; у пустого массива сохраняется одна ось длины ноль.","verified":"3.14","check":{"append":"import numpy as _np\nfor _v, _factor, _expected in [([2, 5], 0.5, [1., 2.5]), ([], 7, []), ([-2, 0, 3], -2, [4., 0., -6.]), ([1], 0, [0.])]:\n    _before = _v.copy()\n    _got = scale_readings(_v, _factor)\n    assert isinstance(_got, _np.ndarray), 'Нужен ndarray, а не список'\n    assert _got.dtype == _np.float64 and _got.shape == (len(_v),), 'Проверьте dtype и shape'\n    assert _np.allclose(_got, _expected), f'values={_v}, factor={_factor}: ожидалось {_expected}, получено {_got.tolist()}'\n    assert _v == _before, 'Исходный список изменился'\nprint('OK')","expect":"OK"}},{"id":"54.3","codeLang":"python","answer":"[6, 9]\n[5, 5, 5]","answerLang":"text","explanation":"axis=0 убирает ось строк: остаётся итог каждого столбца. axis=1 убирает столбцы: остаётся итог каждой строки. Результаты имеют длину 2 и 3.","verified":"3.14","wrong":["[5, 5, 5]\n[6, 9]","15\n15"]},{"id":"54.4","codeLang":"python","answer":"def row_totals(table):\n    return table.sum(axis=1)","answerLang":"python","explanation":"Ось 1 соответствует столбцам. После их суммирования остаётся по числу на каждую строку, в том числе ноль для строки без элементов.","verified":"3.14","check":{"append":"import numpy as _np\nfor _table in [_np.array([[2, 3], [4, 1], [0, 5]]), _np.array([[-1, 2, 7]]), _np.empty((0, 3), dtype=int), _np.empty((2, 0), dtype=int)]:\n    _before = _table.copy()\n    _got = row_totals(_table)\n    _expected = _table.sum(axis=1)\n    assert isinstance(_got, _np.ndarray) and _got.shape == (_table.shape[0],), f'Ожидалась форма {(_table.shape[0],)}'\n    assert _np.array_equal(_got, _expected), f'Ожидалось {_expected.tolist()}, получено {_got.tolist()}'\n    assert _np.array_equal(_table, _before), 'Исходная таблица изменена'\nprint('OK')","expect":"OK"}},{"id":"54.5","codeLang":"python","answer":"import numpy as np\ndef outside_bounds(values, low, high):\n    mask = (values < low) | (values > high)\n    return np.flatnonzero(mask).tolist()","answerLang":"python","explanation":"Скобки отделяют сравнения, | объединяет две булевы маски поэлементно. flatnonzero возвращает позиции True, а не сами измерения. Значения на границе не попадают в результат.","verified":"3.14","check":{"append":"import numpy as _np\nfor _values, _low, _high, _expected in [([1, 2, 5, 9], 2, 5, [0, 3]), ([], 0, 1, []), ([3, 3], 3, 3, []), ([-4, 0, 8], -1, 2, [0, 2]), ([1, 2], 5, 7, [0, 1])]:\n    _v = _np.array(_values, dtype=float)\n    _before = _v.copy()\n    _got = outside_bounds(_v, _low, _high)\n    assert type(_got) is list and all(type(x) is int for x in _got), 'Нужен обычный список индексов'\n    assert _got == _expected, f'values={_values}: ожидалось {_expected}, получено {_got}'\n    assert _np.array_equal(_v, _before), 'Измерения изменились'\nprint('OK')","expect":"OK"}},{"id":"54.6","codeLang":"python","answer":"def shifted_tail(values):\n    tail = values[1:].copy()\n    tail += 1\n    return tail","answerLang":"python","explanation":"Обычный срез ndarray обычно является представлением общей памяти. copy() создаёт независимые данные до изменения. Вариант values[1:] + 1 тоже создаёт новый результат.","verified":"3.14","check":{"append":"import numpy as _np\nfor _values in [[10, 20, 30], [], [7], [-1, 0, 4]]:\n    _v = _np.array(_values, dtype=float)\n    _before = _v.copy()\n    _got = shifted_tail(_v)\n    assert isinstance(_got, _np.ndarray) and _got.shape == (max(0, len(_v)-1),)\n    assert _np.array_equal(_got, _before[1:] + 1), 'Неверный срез или прибавка'\n    assert _np.array_equal(_v, _before), 'Срез изменил исходный массив'\n    assert not _np.shares_memory(_v, _got), 'Результат должен быть независим'\nprint('OK')","expect":"OK"}},{"id":"54.7","codeLang":"python","answer":"[18, 10]","answerLang":"text","explanation":"Форма prices — (3,); она совместима с последней осью таблицы (2, 3). Цены применяются к каждой строке, затем axis=1 собирает стоимость заказа. Это broadcasting, а не матричное умножение.","verified":"3.14","wrong":["[10, 12, 6]","[18, 28]"]},{"id":"54.8","codeLang":"python","answer":"import numpy as np\ndef valid_mean(values):\n    valid = values[np.isfinite(values)]\n    return float(valid.mean()) if valid.size else None","answerLang":"python","explanation":"isfinite исключает и nan, и обе бесконечности. Отбор создаёт массив пригодных измерений, среднее считается по их количеству. Пустоту проверяют до mean(), чтобы не получать предупреждение и nan.","verified":"3.14","check":{"append":"import numpy as _np\nfor _values, _expected in [([2, _np.nan, 4], 3.), ([0, _np.inf, 4], 2.), ([-_np.inf, _np.nan], None), ([], None), ([0, 0], 0.), ([-3, 1], -1.)]:\n    _v = _np.array(_values, dtype=float)\n    _before = _v.copy()\n    _got = valid_mean(_v)\n    assert (_got is None) if _expected is None else (type(_got) is float and _np.isclose(_got, _expected)), f'values={_values}: ожидалось {_expected}, получено {_got}'\n    assert _np.array_equal(_v, _before, equal_nan=True), 'Исходник изменён'\nprint('OK')","expect":"OK"}},{"id":"54.9","codeLang":"python","answer":"import numpy as np\ndef row_shares(table):\n    values = np.array(table, dtype=np.float64, copy=True)\n    totals = values.sum(axis=1, keepdims=True)\n    return np.divide(values, totals, out=np.zeros_like(values), where=totals != 0)","answerLang":"python","explanation":"Сумма с keepdims=True имеет форму (число строк, 1) и подходит для деления каждого столбца своей строки. out задаёт нули там, где where запрещает деление. Источник копируется, поэтому целые числа и исходные измерения сохраняются. Пустые оси тоже имеют форму и не требуют выдуманных измерений.","verified":"3.14","hint":"Проверьте форму суммы строк, нулевой заказ и целочисленный источник по отдельности. Не делите ноль на ноль.","check":{"append":"import numpy as _np\nfor _table, _expected in [(_np.array([[1, 3], [0, 0]]), [[.25, .75], [0., 0.]]), (_np.array([[1., 1., 2.], [2., 0., 0.]]), [[.25, .25, .5], [1., 0., 0.]]), (_np.empty((0, 3)), _np.empty((0, 3))), (_np.empty((2, 0)), _np.empty((2, 0))), (_np.array([[0., 5.]]), [[0., 1.]]), (_np.array([[5.], [0.]]), [[1.], [0.]])]:\n    _before = _table.copy()\n    _got = row_shares(_table)\n    assert isinstance(_got, _np.ndarray) and _got.shape == _table.shape and _got.dtype == _np.float64, 'Сохраните форму и верните float64'\n    assert _np.isfinite(_got).all() and _np.allclose(_got, _expected), f'Для {_before.tolist()} ожидалось {_np.asarray(_expected).tolist()}, получено {_got.tolist()}'\n    assert _np.array_equal(_table, _before), 'Исходная таблица изменилась'\n    assert not _np.shares_memory(_got, _table), 'Результат должен быть новым массивом'\nprint('OK')","expect":"OK"}},{"id":"54.10","codeLang":"python","answer":"import numpy as np\ndef column_means(readings):\n    finite = np.isfinite(readings)\n    counts = finite.sum(axis=0)\n    totals = np.where(finite, readings, 0.0).sum(axis=0)\n    return [float(total / count) if count else None for total, count in zip(totals, counts)]","answerLang":"python","explanation":"В стартере три проблемы: copy=False портит источник, замена пропусков нулями меняет знаменатель среднего, axis=1 считает по строкам. Корректный вариант отдельно хранит маску, сумму и количество настоящих измерений каждого датчика. Нулевой счётчик даёт None. Два настоящих нуля дают 0.0. Проверка прямоугольной таблицей различает оси лучше квадратной.","verified":"3.14","hint":"Проверьте отдельно: источник после вызова, столбец только с пропусками и таблицу с разным числом строк и столбцов.","check":{"append":"import numpy as _np\nfor _table, _expected in [(_np.array([[0., _np.nan], [4., 6.]]), [2., 6.]), (_np.array([[2., _np.inf, 1.], [4., 8., -_np.inf]]), [3., 8., 1.]), (_np.array([[_np.nan, 0.], [_np.inf, 0.]]), [None, 0.]), (_np.empty((0, 3)), [None, None, None]), (_np.empty((2, 0)), []), (_np.array([[-2.], [4.]]), [1.])]:\n    _before = _table.copy()\n    _got = column_means(_table)\n    assert type(_got) is list and len(_got) == len(_expected), 'Нужен один результат на каждый столбец'\n    for _actual, _want in zip(_got, _expected):\n        assert (_actual is None) if _want is None else (type(_actual) is float and _np.isclose(_actual, _want)), f'Ожидалось {_expected}, получено {_got}'\n    assert _np.array_equal(_table, _before, equal_nan=True), 'Не заменяйте пропуски в исходнике'\nprint('OK')","expect":"OK"}}]};
